    "landing.problem1Title": "நீண்ட, கணிக்க முடியாத வரிசைகள்",
    "landing.problem1Body": "விவசாயிகள் வந்துவிடுகிறார்கள், ஆனால் எவ்வளவு நேரம் காத்திருக்க வேண்டும் என்று தெரியாது.",
