    "landing.problem2Body": "பலர் ஒரே நேரத்தில் வருகிறார்கள், அதைப் பிரித்துக் கொள்ள வழியில்லை.",
    "landing.problem3Title": "தெளிவு இல்லை",
    "landing.problem3Body": "விளைபொருளை ஒப்படைத்த பிறகு, பணம் வரும் வரை அதன் நிலை தெரியாது.",
    "landing.problem4Title": "பணிச்சுமையைக் கண்காணிப்பது கடினம்",
    "landing.problem4Body": "எந்த இடங்களில் அதிகச் சுமை என்பதை மைய மேலாளர்கள் எளிதில் காண முடியாது.",
    "landing.solutionTitle": "இந்த தளம் என்ன செய்கிறது",
    "landing.sol1": "கொள்ளளவுக்கு ஏற்ற ஸ்லாட் முன்பதிவு, அதனால் ஸ்லாட் அதிகமாக முன்பதிவாகாது",
    "landing.sol2": "நேரில் வரிசையில் நிற்பதற்குப் பதிலாக டிஜிட்டல் டோக்கன்",
    "landing.sol3": "நேரலை வரிசை நிலை, உடனுக்குடன் புதுப்பிக்கப்படும்",
    "landing.sol4": "AI மதிப்பிட்ட காத்திருப்பு நேரம், மதிப்பீடு என்று தெளிவாகக் குறிக்கப்படும்",
    "landing.sol5": "உங்கள் விளைபொருள் கடக்கும் ஒவ்வொரு படியின் தெரியும் பதிவு",
    "landing.sol6": "பில் முதல் வரவு வரை பணம் செலுத்தும் நிலை கண்காணிப்பு",
    "landing.howTitle": "இது எப்படி செயல்படுகிறது",
    "landing.step1": "உங்கள் அடிப்படை விவரங்களுடன் ஒருமுறை பதிவு செய்யுங்கள்",
    "landing.step2": "உங்கள் மையத்தைத் தேர்ந்தெடுத்து கிடைக்கும் ஸ்லாட்களைப் பாருங்கள்",
    "landing.step3": "ஸ்லாட்டை முன்பதிவு செய்து உங்கள் டோக்கனைப் பெறுங்கள்",
    "landing.step4": "வரிசையில் உங்கள் நிலையை நேரலையில் கண்காணியுங்கள்",
    "landing.step5": "வீட்டை விட்டு கிளம்பும் முன் AI மதிப்பிட்ட காத்திருப்பு நேரத்தைப் பாருங்கள்",
    "landing.step6": "மையத்திற்கு வந்து சரிபார்ப்பு செய்து கொள்ளுங்கள்",
    "landing.step7": "உங்கள் பயிரின் தரம் சோதிக்கப்பட்டு எடை போடப்படும்",
    "landing.step8": "பணம் வரவு வைக்கப்படும் வரை உங்கள் பணம் செலுத்தும் நிலையைக் கண்காணியுங்கள்",
    "landing.helpsTitle": "இது யாருக்கு உதவுகிறது",
    "landing.forFarmers": "விவசாயிகளுக்கு",
    "landing.farmer1": "காத்திருப்பு நேரம் குறித்த குறைவான நிச்சயமின்மை",
