    "landing.farmer3": "வரிசையில் உங்கள் நிலையைப் பார்க்கும் வசதி",
    "landing.farmer4": "உங்கள் கொள்முதலின் வெளிப்படையான பதிவு",
    "landing.forCentres": "மையங்களுக்கு",
