    "emg.reason.rainSignificant": "{place} இல் கனமழை: 24 மணி நேரத்தில் {mm24} மி.மீ (ஒரு மணியில் அதிகபட்சம் {peak} மி.மீ).",
    "emg.reason.rainModerate": "{place} இல் மிதமான மழை: 24 மணி நேரத்தில் {mm24} மி.மீ.",
    "emg.reason.windStrong": "{place} இல் பலத்த காற்று: {gust} கி.மீ/மணி வரை.",
    "emg.reason.supportAtCentreOnly": "கடுமையான வானிலை மையத்தில் அல்லது அதைச் சுற்றி இருந்தது. விவசாயியின் இடம் தெரியாததால், அவர் பயணிக்க முடியவில்லை என்பதை இது மட்டும் நிரூபிக்காது.",
    "emg.reason.alertFound": "{count} அதிகாரப்பூர்வ வானிலை எச்சரிக்கை(கள்), எ.கா: {headline}",
    "emg.reason.dryAtReportedLocation": "விவசாயி கூறிய இடத்திலும் அருகிலும் வறண்டிருந்தது ({mm} மி.மீ). இது கூற்றுடன் பொருந்தவில்லை. அதிகாரி கவனமாகப் பார்க்கவும்.",
    "emg.reason.noWeatherSupport": "வானிலை பதிவுகளில் கடுமையான வானிலை தெரியவில்லை; ஆனால் விவசாயியின் சரியான இடம் தெரியாததால் இது கூற்றுக்கு எதிரான சான்று அல்ல.",
    "emg.reason.needsEvidence": "வானிலை கூற்றை ஆதரிக்கிறது, ஆனால் இன்னும் புகைப்படம் / கோப்பு இல்லை.",
    "emg.reason.farFromCentre": "தெரிவித்த இடம் மையத்திலிருந்து சுமார் {km} கி.மீ தொலைவில் உள்ளது.",
    "emg.reason.verificationError": "தானியங்கி சரிபார்ப்பில் சிக்கல். கோரிக்கையை நேரில் பரிசீலிக்கவும்.",
